import { useState, useEffect } from 'react';
import { AuthProvider, useAuth } from './context/AuthContext';
import LoginPage              from './pages/LoginPage';
import DashboardPage          from './pages/DashboardPage';
import EmployeesPage          from './pages/EmployeesPage';
import TemplatesPage          from './pages/TemplatesPage';
import LettersPage            from './pages/LettersPage';
import ApprovalsPage          from './pages/ApprovalsPage';
import ExitPage               from './pages/ExitPage';
import AppointmentOrdersPage  from './pages/AppointmentOrdersPage';
import EmployeeSectionsPage   from './pages/EmployeeSectionsPage';
import EmployeeDashboardPage  from './pages/EmployeeDashboardPage';
import Layout                 from './components/Layout';
import './App.css';

// ── Hash-based router ────────────────────────────────────────────────────────
function useHashRoute() {
  const getPath = () => window.location.hash.replace(/^#+/, '') || '/';
  const [path, setPath] = useState(getPath);
  useEffect(() => {
    const handler = () => setPath(getPath());
    window.addEventListener('hashchange', handler);
    return () => window.removeEventListener('hashchange', handler);
  }, []);
  return path;
}

// ── HR / Admin pages ─────────────────────────────────────────────────────────
const HR_PAGES = {
  '/':                DashboardPage,
  '/employees':       EmployeesPage,
  '/employee-sections': EmployeeSectionsPage,
  '/templates':       TemplatesPage,
  '/letters':         LettersPage,
  '/approvals':       ApprovalsPage,
  '/exit':            ExitPage,
  '/appointment-orders': AppointmentOrdersPage,
};

function NotFound() {
  return (
    <div style={{ textAlign: 'center', padding: '80px 20px' }}>
      <div style={{ fontSize: 48, marginBottom: 16 }}>◎</div>
      <h2 style={{ fontFamily: 'var(--display)', marginBottom: 8 }}>404 — Page not found</h2>
      <button className="btn btn-primary" onClick={() => { window.location.hash = '/'; }}>
        Go to Dashboard
      </button>
    </div>
  );
}

function AppRouter() {
  const path              = useHashRoute();
  const { user, loading } = useAuth();

  if (loading) return <div className="loading-screen"><div className="spinner" /></div>;
  if (!user)   return <LoginPage />;

  // ── Employee self-service portal (role = 'employee') ──────────────────────
  // Employees get a dedicated sidebar layout with only their documents visible.
  if (user.role === 'employee') {
    return <EmployeeDashboardPage />;
  }

  // ── HR / Manager / HR Head / Admin ────────────────────────────────────────
  const PageComponent = HR_PAGES[path] ?? NotFound;
  return (
    <Layout currentPath={path}>
      <PageComponent />
    </Layout>
  );
}

export default function App() {
  return (
    <AuthProvider>
      <AppRouter />
    </AuthProvider>
  );
}
